const CHARACTER_DB="aibc-oddling-assets-v1";
function selectedOddling(){const id=Number(state.settings?.selectedCharacterId||1);return ODDLINGS.find(x=>x.id===id)||ODDLINGS[0]}
function oddlingPalette(key){const colors={mint:"#59d1a6",plum:"#4d1f57",gold:"#ffb82e",coral:"#fa6b5b",cream:"#f5d6a0",teal:"#168c8c",lime:"#addf38",forest:"#1a5733",orange:"#ff7417",lavender:"#ad8ce6",indigo:"#352978",silver:"#b8c5d8",sky:"#5cb8f2",navy:"#142956",pink:"#f566ad",peach:"#faa676",chocolate:"#4d2714",yellow:"#ffd52d",aqua:"#38d1d1",blue:"#296be8",red:"#d91f30",olive:"#687b20",purple:"#7c35b7",rose:"#e05c85",maroon:"#66152f",ice:"#b9e0ef",slate:"#40576f",cyan:"#20d9e8",rust:"#9e3815",deepteal:"#06454a",moss:"#718a38",pine:"#204020",magenta:"#df219d",sand:"#c69e61",umber:"#57331f",turquoise:"#19b7b0",periwinkle:"#7c8de5",bluegray:"#4d628f",tan:"#b37a48",cocoa:"#522918",emerald:"#159653",darkgreen:"#0c361f",lilac:"#c39be5",violet:"#7023a8",charcoal:"#30343d",black:"#11131a",ember:"#ff4808",pistachio:"#a6c763",green:"#31883a",electric:"#37cbe0",berry:"#a51654",taupe:"#7a6250",royal:"#2845aa",bubblegum:"#f28ac4"};return colors[key]||"#8a91a6"}
function oddlingStore(){return new Promise((resolve,reject)=>{const req=indexedDB.open(CHARACTER_DB,1);req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains("models"))req.result.createObjectStore("models")};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function getOddlingModel(id){const db=await oddlingStore();return new Promise((resolve,reject)=>{const req=db.transaction("models").objectStore("models").get(String(id));req.onsuccess=()=>resolve(req.result||null);req.onerror=()=>reject(req.error)})}
async function saveOddlingModels(rows){const db=await oddlingStore();return new Promise((resolve,reject)=>{const tx=db.transaction("models","readwrite"),store=tx.objectStore("models");for(const row of rows)store.put(row.blob,String(row.id));tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)})}
