function providerSettingsPanel(){return "<section class=\"panel section-gap\"><div class=\"panel-head\"><div><h2>🔐 راه‌اندازی رایگان هوش مصنوعی Google</h2><p>برای ساخت متن و گویندگی انگلیسی، یک کلید رایگان از Google AI Studio لازم است. ساخت کلید رایگان است؛ سهمیه محدود دارد و نامحدود نیست. کلید فقط در Worker با AES-GCM رمزگذاری می‌شود و در مرورگر ذخیره نمی‌شود.</p></div></div><div class=\"actions\"><a class=\"button primary\" href=\"https://aistudio.google.com/app/apikey\" target=\"_blank\" rel=\"noopener noreferrer\">ساخت کلید رایگان در Google AI Studio ↗</a></div><ol class=\"muted gemini-steps\"><li>با حساب Google وارد شو.</li><li>گزینه Create API key را انتخاب کن و یک پروژه بساز یا انتخاب کن.</li><li>کلید را کپی کن و فقط در کادر امن زیر قرار بده.</li></ol><form id=\"provider-form\" class=\"form-fields\"><div class=\"field\"><label>کلید API رایگان Google AI Studio</label><input name=\"geminiKey\" type=\"password\" autocomplete=\"off\" spellcheck=\"false\" placeholder=\"کلید Gemini را اینجا وارد کن\"></div><p class=\"muted\">این کلید برای Gemini 2.5 Flash (متن) و Gemini TTS (گویندگی انگلیسی) استفاده می‌شود. بدون کلید، تولید هوش مصنوعی شروع نمی‌شود؛ هیچ سرویس پولی جایگزین نخواهد شد. سهمیه رایگان محدود است و داده‌های ارسالی ممکن است طبق سیاست Google برای بهبود محصولات استفاده شوند.</p><div class=\"actions\"><button class=\"button primary\" type=\"submit\">ذخیره امن کلید Gemini</button><button class=\"button secondary\" type=\"button\" data-action=\"media-check\">بررسی وضعیت کلید</button></div></form><div id=\"media-capabilities\" class=\"muted\"></div></section>"}
function settings(){const services=[["youtube","یوتیوب","youtube"]];return heading("اتصال‌ها","تنظیمات","مدیریت نشست امن و اتصال واقعی حساب Google/YouTube.", "")+'<section class="panel"><div class="panel-head"><h2>توکن دسترسی برنامه</h2><span class="pill">'+(cloudToken?"نشست فعال":"نیازمند ورود")+'</span></div><div class="field"><label for="cloud-workspace">شناسه فضای کاری</label><input id="cloud-workspace" value="'+esc(localStorage.getItem("ai-business-core-workspace-v1")||"default")+'" maxlength="64" dir="ltr" autocomplete="off"></div><p class="muted">توکن APP_ACCESS_TOKEN فقط برای برقراری نشست امن با Worker استفاده می‌شود و فقط در sessionStorage همین مرورگر نگهداری خواهد شد.</p><div class="field"><label for="cloud-token">توکن برنامه</label><input id="cloud-token" type="password" autocomplete="new-password" spellcheck="false" placeholder="توکن APP_ACCESS_TOKEN را وارد کن" maxlength="512"></div><div class="actions"><button class="button primary" data-action="cloud-connect">اتصال امن و بررسی توکن</button><button class="button secondary" data-action="cloud-disconnect">قطع نشست این دستگاه</button></div><p id="token-session-status" class="muted">'+(cloudToken?"نشست برنامه در این مرورگر فعال است.":"توکنی در این نشست وارد نشده است.")+'</p><div class="actions"><button class="button secondary" data-action="cloud-push">پشتیبان‌گیری در فضای ابری</button><button class="button secondary" data-action="cloud-pull">بازیابی از فضای ابری</button></div>'+(cloudConflict?'<div class="cloud-conflict-panel"><strong>تعارض داده‌ها؛ هیچ نسخه‌ای حذف نشده است.</strong><p class="muted">با ادغام امن، ابتدا از داده‌های این گوشی نسخه پشتیبان می‌گیریم و سپس داده‌های محلی و ابری را بدون جایگزینی کامل ترکیب می‌کنیم.</p><button class="button primary" data-action="cloud-merge">پشتیبان‌گیری و ادغام امن دو نسخه</button></div>':'')+'</section><section class="panel"><div class="panel-head"><div><h2>اتصال حساب Google و YouTube</h2><p class="muted">برای دسترسی به کانال، آمار و بارگذاری ویدئو باید حساب گوگل را جداگانه مجاز کنی.</p></div><span class="pill">OAuth امن</span></div><p class="muted">پس از شروع، به صفحه رسمی Google منتقل می‌شوی. انتخاب حساب و تأیید مجوزها در اختیار توست؛ توکن‌های Google به‌صورت رمزگذاری‌شده در فضای کاری ذخیره می‌شوند.</p><div class="actions"><button class="button primary" data-action="youtube-connect">اتصال حساب Google / YouTube</button><button class="button secondary" data-action="check-connection" data-service="youtube">بررسی وضعیت کانال</button></div><p class="muted">اگر چند کانال داری، با حسابی وارد شو که مالک یا مدیر کانال موردنظر است.</p></section><section class="panel"><div class="panel-head"><h2>وضعیت اتصال YouTube</h2><span class="muted">فقط وضعیت واقعی کانال متصل نمایش داده می‌شود.</span></div><div class="connection-list">'+services.map(([key,label])=>'<div class="connection-row"><div><strong>'+label+'</strong><p id="connection-'+key+'" class="muted">بررسی نشده</p></div><button class="button secondary" data-action="check-connection" data-service="'+key+'">بررسی اتصال</button></div>').join("")+'</div></section><section class="panel"><div class="panel-head"><h2>پیش‌نمایش خطاها</h2><button class="button secondary" data-action="copy-errors">کپی گزارش خطاها</button></div><p class="muted">خطاهای برنامه و اتصال‌ها برای عیب‌یابی اینجا ثبت می‌شوند؛ پیش از ارسال گزارش، اطلاعات محرمانه را بررسی کن.</p><div id="error-log-preview" class="error-log-preview">'+renderErrorLog()+'</div><div class="actions"><button class="button secondary" data-action="clear-errors">پاک‌کردن گزارش خطاها</button></div></section>'}


async function uploadGeneratedVideo(privacyStatus="private"){const token=(aiToken||cloudToken||$("#cloud-token")?.value||"").trim(),wid=($("#cloud-workspace")?.value||"default").trim();if(token.length<24)throw Error("ابتدا توکن دسترسی برنامه را در تنظیمات وارد کن.");if(!generatedVideoBlob)throw Error("ابتدا ویدئوی کوتاه را بساز.");if(generatedVideoBlob.size>64*1024*1024)throw Error("حجم ویدئو از محدودیت فعلی ۶۴ مگابایت بیشتر است.");const meta=generatedVideoMetadata||{},title=String(meta.title||$("#ai-topic")?.value||"ویدئوی آموزشی").slice(0,100),description=String(meta.description||"ویدئوی آموزشی تولیدشده با AI Business Core").slice(0,5000),tags=Array.isArray(meta.tags)?meta.tags.join(", "):"AI education, artificial intelligence";const body=new FormData();body.append("video",new File([generatedVideoBlob],generatedVideoBlob.type==="video/mp4"?"nexora-ai-short.mp4":"nexora-ai-short.webm",{type:generatedVideoBlob.type||"video/webm"}));body.append("title",title);body.append("description",description);body.append("tags",tags);body.append("privacyStatus",privacyStatus);if(privacyStatus==="public")body.append("confirmPublic","true");const response=await workerFetch("https://ai-business-core.mohammadfadaiemacbook.workers.dev/api/youtube/upload?workspace="+encodeURIComponent(wid),{method:"POST",headers:{authorization:"Bearer "+token},body,timeoutMs:180000});const data=await response.json().catch(()=>({}));if(!response.ok)throw Error((data.error||"بارگذاری خصوصی در یوتیوب ناموفق بود"));const result=$("#video-studio-result");if(result)result.insertAdjacentHTML("beforeend",'<p class="muted">ویدئو فقط به‌صورت خصوصی بارگذاری شد: <a href="'+esc(data.url)+'" target="_blank" rel="noopener">'+esc(data.title)+'</a> · وضعیت: '+esc(data.privacyStatus)+'</p>');return data;}
function render(){let root=$("#view-root");if(!root){console.error("Cannot render app: #view-root is missing.");return;}state.settings={...empty().settings,...(state.settings&&typeof state.settings==="object"?state.settings:{})};try{root.innerHTML=({overview, youtube:youtubeStudio, tasks:()=>listPage("tasks","مدیریت وظایف","وظایف پژوهش، تولید محتوا و عملیات را پیگیری کنید."),research:()=>listPage("research","کتابخانه پژوهش","منابع، مشاهدات و فرضیه‌ها را با برچسب مشخص نگهداری کنید."),content:()=>listPage("content","استودیو محتوا","محتوای ویدئویی و شبکه‌های اجتماعی را از ایده تا بازبینی مدیریت کنید."),calendar,approvals:()=>listPage("approvals","صف تأییدها","اقدام‌های پیشنهادی را بررسی کنید. تأییدها به‌معنای اجرای عملیات در پلتفرم‌ها نیستند."),settings,ai:aiStudio})[view]();}catch(error){console.error("View render failed:",view,error);root.innerHTML='<section class="panel"><h2>بارگذاری این بخش کامل نشد</h2><p class="muted">اطلاعات محلی حفظ شده است. صفحه را دوباره بارگذاری کن؛ اگر مشکل ماند، گزارش خطا را بررسی می‌کنیم.</p><button class="button primary" type="button" data-action="retry-render">تلاش دوباره</button></section>';}if(view==="youtube"){void renderOddlingLibrary();const s=state.settings||{};const set=(id,value)=>{const el=$("#"+id);if(el)el.value=value};set("yt-channel-name",s.youtubeChannelName||"Nexora AI");set("yt-region",s.youtubeRegion||"US");set("yt-niche",s.youtubeNiche||"AI education, AI tools, agents and automation");set("yt-audience",s.youtubeAudience||"Global English-speaking audience")}const breadcrumb=$("#breadcrumb-current");if(breadcrumb)breadcrumb.textContent=names[view]||"Overview";document.querySelectorAll(".nav-item[data-view]").forEach(x=>x.classList.toggle("active",x.dataset.view===view));const taskCount=$("#nav-task-count");if(taskCount)taskCount.textContent=state.tasks.filter(x=>x.status!=="Done").length;const approvalCount=$("#nav-approval-count");if(approvalCount)approvalCount.textContent=state.approvals.filter(x=>x.status==="Pending").length}
function openForm(type,item){let s=schemas[type];if(!s)return;editing=item?.id||null;editingType=type;$("#dialog-title").textContent=(item?"ویرایش ":"افزودن ")+s.label.toLowerCase();$("#dialog-fields").innerHTML=s.fields.map(([n,l,k,req,opts])=>{let v=item?.[n]??(n==="date"&&type==="research"?new Date().toISOString().slice(0,10):"");let required=req?" required":"";if(k==="textarea")return '<div class="field"><label for="f-'+n+'">'+l+'</label><textarea id="f-'+n+'" name="'+n+'" rows="4" maxlength="10000"'+required+'>'+esc(v)+'</textarea></div>';if(k==="select")return '<div class="field"><label for="f-'+n+'">'+l+'</label><select id="f-'+n+'" name="'+n+'">'+opts.map(o=>'<option value="'+esc(o)+'" '+(v===o?"selected":"")+'>'+esc(fa(o))+'</option>').join("")+'</select></div>';return '<div class="field"><label for="f-'+n+'">'+l+'</label><input id="f-'+n+'" name="'+n+'" type="'+k+'" value="'+esc(v)+'" maxlength="500"'+required+'></div>'}).join("");$("#dialog-save").textContent=item?"ذخیره تغییرات":"ذخیره مورد";$("#item-dialog").showModal()}
